const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let trips=[],book=null,busy=false,cancel=false,controller=null,cache=new Map(),mapReady=false;
const map=new maplibregl.Map({container:'map',style:'map-style.json',center:[120.5,32],zoom:4.5,attributionControl:{customAttribution:['站点服务 <a href="https://www.openrailwaymap.org/">OpenRailwayMap</a>','铁路寻路 <a href="https://brouter.de/">BRouter</a>']}});map.addControl(new maplibregl.NavigationControl(),'top-right');
map.on('load',()=>{mapReady=true;map.addSource('journeys',{type:'geojson',data:collection()});map.addLayer({id:'journey-outline',type:'line',source:'journeys',paint:{'line-color':'#66727e','line-width':['match',['get','mode'],'air',2,5.5],'line-opacity':['match',['get','mode'],'air',.55,0]}});map.addLayer({id:'journey-lines',type:'line',source:'journeys',paint:{'line-color':['match',['get','mode'],'air','#e4eaf2','#dc3038'],'line-width':['match',['get','mode'],'air',1.2,3.5],'line-opacity':['match',['get','mode'],'air',1,.58]}});map.addSource('stops',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'stop-points',type:'circle',source:'stops',paint:{'circle-radius':4,'circle-color':'#fff','circle-stroke-color':'#33755b','circle-stroke-width':2}});map.addLayer({id:'journey-hit',type:'line',source:'journeys',filter:['==',['get','clickable'],true],paint:{'line-width':16,'line-opacity':0}});map.on('click','journey-hit',showMapCards);map.on('mouseenter','journey-hit',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','journey-hit',()=>map.getCanvas().style.cursor='');draw()});
map.on('error',()=>{if(!mapReady)$('status').textContent='地图资源加载中；若持续空白，请检查网络后刷新。'});
function visible(){const f=$('filter').value,q=$('search').value.toLowerCase();return trips.filter(t=>(f==='all'||f===t.mode||f==='error'&&t.error)&&[t.from,t.to,t.raw['班次'],t.sheet].join(' ').toLowerCase().includes(q)).sort(TripData.newest)}
function collection(){const counts=TripData.counts(trips),paths=displayPaths();return {type:'FeatureCollection',features:visible().filter(t=>t.path).map(t=>({type:'Feature',properties:{id:t.id,clickable:TripData.clickable(t,counts),count:counts.get(TripData.key(t))||1,date:t.time?.label||'',departure:t.time?.departure||'',mode:t.mode,from:t.from,to:t.to,sheet:t.sheet,row:t.row,routeBasis:t.routeBasis||'',timetableVersion:t.timetable?.version||'',routingNote:t.routingNote||'',status:t.mode==='rail'?(t.routeBasis||'OSM 网络推算'):'机场间椭圆弧线'},geometry:Core.geoJSONPath(paths.get(t.id))}))}}
function draw(){if(!mapReady)return;map.getSource('journeys').setData(collection());map.getSource('stops').setData({type:'FeatureCollection',features:visible().filter(t=>t.path).flatMap(t=>[t.path[0],t.path.at(-1)].map(p=>({type:'Feature',properties:{},geometry:{type:'Point',coordinates:[p[1],p[0]]}})))})}
function fit(path){const paths=displayPaths();let p=path||visible().flatMap(t=>paths.get(t.id)||[]);if(!p.length)return;const b=new maplibregl.LngLatBounds();p.forEach(x=>b.extend([x[1],x[0]]));map.fitBounds(b,{padding:{top:150,bottom:130,left:65,right:65},maxZoom:16})}
function render(){mapPopup?.remove();let list=visible();$('count').textContent=trips.length;$('total').innerHTML=trips.length+'<small> 段</small>';$('done').innerHTML=trips.filter(t=>t.path).length+'<small> 段</small>';let ds=trips.map(t=>Number(t.raw['里程'])).filter(v=>Number.isFinite(v)&&v>0);$('distance').innerHTML=(ds.length?Math.round(ds.reduce((a,b)=>a+b,0)).toLocaleString():'—')+'<small> km</small>';$('run').disabled=!trips.length||busy;$('list').innerHTML=list.length?list.map(t=>`<div class="trip" data-id="${t.id}"><strong>${t.mode==='air'?'✈':'▤'} ${esc(t.from||'缺少出发地')} <span style="color:#a8b4aa">→</span> ${esc(t.to||'缺少到达地')}</strong><small>${esc(t.time?.label||t.raw['日期'])} ${esc(t.time?.departure||'')} · ${esc(t.raw['班次']||'未填班次')} · ${esc(t.sheet)} #${t.row}</small><small class="${t.error?'bad':''}">${esc([t.error||t.status||'待生成',t.time?.note,t.routingNote].filter(Boolean).join(' · '))}</small></div>`).join(''):'<div class="empty"><span>⌁</span><h3>'+(trips.length?'没有符合筛选条件的行程':'暂无行程')+'</h3><p>导入后显示行程与匹配结果。</p></div>';draw()}
function tell(s){$('status').textContent=s}
function modal(html){$('detail').innerHTML=html;$('dialog').showModal()}
$('close').onclick=()=>$('dialog').close();$('fit').onclick=()=>fit();$('filter').onchange=render;$('search').oninput=render;$('list').onclick=e=>{let el=e.target.closest('[data-id]');if(el)showTrip(trips.find(t=>t.id===Number(el.dataset.id)))};
const headers=['日期','出发地','到达地','班次','承运','席位','出发时间','到达时间','价格','型号','里程','腐败率'];
$('template').onclick=()=>{if(!window.XLSX)return tell('表格组件未加载，请检查网络后刷新');let w=XLSX.utils.book_new();XLSX.utils.book_append_sheet(w,XLSX.utils.aoa_to_sheet([headers]),'行程');XLSX.writeFile(w,'行迹-空白行程模板.xlsx')};
$('help').onclick=()=>modal('<h2>导入格式说明</h2><p>按列名识别，不依赖列顺序。必填列为「出发地」「到达地」，其余列可留空。扫描工作表前 100 行寻找表头，读取之后的全部有效记录。</p><pre>'+headers.join(' / ')+'</pre><p>车站使用精确站名；飞行起终点使用 IATA 三字码。三个英文字母的起终点会识别为飞行，也可在行程详情修正。年份从日期单元格或 Sheet 名识别；无年份仍可生成轨迹。腐败率表示每公里单价。支持中文、日文站名，以及可选「途经站」列（用 ; 分隔）。年度 Sheet（如 2019—2026 各一个 Sheet）中的 5.5 识别为该年 5 月 5 日；完整日期优先使用自身年份。按日期及出发时间倒序，未知日期排最后。若 5.10 在 Excel 中存为数值 5.1，无法还原 10 日，请使用文本或日期单元格。</p><p>地图点击显示详情卡片；所有航班可点选，铁路同一对精确站名的去返程合计不超过 6 次可点选（一次往返计 2 次）。次数按当前导入的全部记录统计，不随筛选变化。超过 6 次仍显示轨迹，可从左侧列表查看。多 Sheet 可选择单个或全部；不会自动去重。空白行跳过，缺少起终点的记录保留并提示。公式读取文件中的缓存值，错误单元格视为空；本应用不执行公式。</p><p>中国铁路优先按日期和车次读取 RailLog 历史停站快照，截取起终站区间并约束 OSM 分段寻路；快照并非当日实际开行记录。路路通查询结果可经人工核对后填入途经站。没有可用时刻表时明确标记为 OSM 网络推算；有歧义的同名站结合承运方与起终站自动匹配。网络断开时不绘制直线替代。跨区域长线路可添加途经站分段查询。</p><p>地图：OSM / OpenFreeMap；地形阴影：Mapzen DEM。只显示城市、主要公路、铁路、水系和地形。表格在浏览器内处理；机场坐标从本站坐标库读取；默认将站名发送至 OpenRailwayMap 站点索引、车站坐标发送至 BRouter 的铁路模式；仅选择备用 Overpass 模式时发送铁路查询范围至 Overpass；启用历史时刻表时，车次号和快照版本发送至 RailLog。刷新后数据不保留，可导出 GeoJSON。</p>');
async function openFile(file){if(!file||busy)return;if(!/\.xlsx?$/i.test(file.name))return tell('请选择 .xlsx 或 .xls 文件');try{if(!window.XLSX)throw Error('表格组件未加载，请检查网络');book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false,cellNF:true});$('sheet').innerHTML='<option value="">请选择工作表…</option>'+(book.SheetNames.length>1?'<option value="*">全部 Sheet</option>':'')+book.SheetNames.map((s,i)=>`<option value="${i}">${esc(s)}</option>`).join('');$('sheetBox').hidden=false;if(book.SheetNames.length===1){$('sheet').value='0';parseSheets()}else{modal('<h2>选择要生成的工作表</h2><p>检测到 '+book.SheetNames.length+' 个 Sheet。可读取其中一个，或合并全部 Sheet 的行程。</p><select id="choose">'+$('sheet').innerHTML+'</select><p id="choiceError"></p><button class="primary" id="confirmSheet">读取所选数据</button>');$('confirmSheet').onclick=()=>{if(!$('choose').value){$('choiceError').textContent='请先选择一个 Sheet 或全部 Sheet';return}$('sheet').value=$('choose').value;$('dialog').close();parseSheets()}}}catch(e){tell('读取失败：'+e.message)}}
$('file').onchange=e=>{openFile(e.target.files[0]);e.target.value=''};$('drop').ondragover=e=>e.preventDefault();$('drop').ondrop=e=>{e.preventDefault();openFile(e.dataTransfer.files[0])};$('sheet').onchange=parseSheets;
function parseSheets(){if(busy||!book||!$('sheet').value)return;const names=$('sheet').value==='*'?book.SheetNames:[book.SheetNames[Number($('sheet').value)]],notes=[];trips=[];for(const name of names){let ws=book.Sheets[name],range=ws['!ref']?XLSX.utils.decode_range(ws['!ref']):null;if(!range){notes.push(name+'：空表');continue}let rows=XLSX.utils.sheet_to_json(ws,{header:1,raw:false,defval:'',blankrows:true}),hi=rows.slice(0,100).findIndex(r=>r.map(x=>String(x).trim()).includes('出发地')&&r.map(x=>String(x).trim()).includes('到达地'));if(hi<0){notes.push(name+'：未找到出发地/到达地表头');continue}let keys=rows[hi].map(x=>String(x).trim());for(let i=hi+1;i<rows.length;i++){let row=rows[i];if(String(row[keys.indexOf('出发地')]||'').trim()==='出发地'&&String(row[keys.indexOf('到达地')]||'').trim()==='到达地')continue;if(!row.some(x=>String(x).trim()))continue;let raw={};keys.forEach((k,j)=>{if(k)raw[k]=String(row[j]??'').trim().replace(/^#(DIV\/0!|VALUE!|N\/A|REF!|NAME\?|NUM!|NULL!)$/,'')});if(keys.every(k=>!raw[k]))continue;let from=raw['出发地']||'',to=raw['到达地']||'';const dateCol=keys.indexOf('日期');const dc=dateCol<0?null:ws[XLSX.utils.encode_cell({r:range.s.r+i,c:range.s.c+dateCol})];const time=TripData.date(raw,name,dc?{...dc,dateFormatted:XLSX.SSF.is_date(dc.z||'')}:null,!!book.Workbook?.WBProps?.date1904);trips.push({id:trips.length,time,raw,from,to,sheet:name,row:range.s.r+i+1,mode:/^[a-z]{3}$/i.test(from)&&/^[a-z]{3}$/i.test(to)?'air':'rail',via:raw['途经站']||'',error:!from||!to?'缺少出发地或到达地':''})}}render();tell('已读取 '+names.length+' 个 Sheet，共 '+trips.length+' 条记录'+(notes.length?'；'+notes.join('；'):''));if(notes.length)modal('<h2>工作表读取结果</h2><p>已导入 '+trips.length+' 条行程。</p><pre>'+esc(notes.join('\n'))+'</pre>')}
async function overpass(q){if(cancel)throw Error('已停止');return Services.overpass(q,controller?.signal,message=>tell(message))}
function normalize(s){return s.trim().replace(/(站|駅)$/,'')}
async function locateManyOverpass(names,trip){
 if(trip.mode==='air')return Promise.all(names.map(n=>trip.overrides?.[n]||Services.airport(n,controller?.signal)));
 const required=[...new Set(names.filter(n=>!trip.overrides?.[n]))],found=new Map();
 const variants=n=>{const v=StationMatch.aliases[n]||n;return [...new Set([v,normalize(v),normalize(v)+'站',normalize(v)+'駅'])]};
 const query=(values,keys)=>'('+[...new Set(values)].flatMap(v=>keys.map(k=>'nwr["railway"~"^(station|halt)$"]["'+k+'"='+JSON.stringify(v)+'];')).join('')+');out center tags;';
 function collect(els,requested){for(const n of requested){const accepted=variants(n);let candidates=[];for(const e of els){const tags=e.tags||{},pos=e.center||e;if(!['name','name:zh','name:ja'].some(k=>accepted.includes(tags[k]))||!Number.isFinite(pos.lat)||!Number.isFinite(pos.lon))continue;const operator=tags.operator||tags.network||'';if(!candidates.some(c=>c.operator===operator&&Core.km(c.xy,[pos.lat,pos.lon])<.12))candidates.push({name:tags.name||n,operator,xy:[pos.lat,pos.lon]})}if(candidates.length)found.set(n,candidates)}}
 if(required.length){tell('批量匹配 '+required.length+' 个铁路车站');collect(await overpass(query(required.map(n=>StationMatch.aliases[n]||n),['name'])),required);const missing=required.filter(n=>!found.has(n));if(missing.length)collect(await overpass(query(missing.flatMap(variants),['name','name:zh','name:ja'])),missing)}
 const points=[];for(const n of names){if(trip.overrides?.[n]){points.push(trip.overrides[n]);trip._lastPoint=trip.overrides[n];continue}const candidates=found.get(n);if(!candidates?.length)throw Error('OSM 未找到车站 '+n+'，请核对站名');const point=StationMatch.rank(candidates,n,trip)[0].xy;trip._lastPoint=point;points.push(point)}return points;
}
async function locateMany(names,trip){if(trip.mode==='air'||$('routing').value==='overpass')return locateManyOverpass(names,trip);return RailService.locate(names,trip,controller?.signal,tell)}
async function locate(name,mode,trip){return (await locateMany([name],trip||{mode,raw:{}}))[0]}

async function railNetwork(points,trip){const lat=points.map(p=>p[0]),lon=points.map(p=>p[1]),d=Math.max(...points.map(p=>Core.km(points[0],p)));if(d>900)throw Error('单段超过 900 km，请添加途经站分段查询');const margin=Math.max(.02,Math.min(1,d/600)),box=[Math.max(-85,Math.min(...lat)-margin),Math.max(-180,Math.min(...lon)-margin),Math.min(85,Math.max(...lat)+margin),Math.min(180,Math.max(...lon)+margin)],kinds=StationMatch.context(trip||{}).operator?'rail':'rail|light_rail|subway|monorail|tram|narrow_gauge';return overpass('way["railway"~"^('+kinds+')$"]["service"!~"^(yard|siding|spur)$"]('+box.join(',')+');out geom;')}
async function railway(a,b,exactStart=false,startNodeId=null,trip=null,network=null){return Core.route(network||await railNetwork([a,b],trip),a,b,{exactStart,startNodeId})}

async function generate(t){delete t._lastPoint;t.error='';t.candidates=null;delete t.path;if(!t.from||!t.to)throw Error('缺少出发地或到达地');if(t.from===t.to&&!t.via.trim())throw Error('起终点相同，请提供环线途经站；航空起终机场不能相同');let names=[t.from,...(t.mode==='rail'?t.via.split(/[;；]/).map(s=>s.trim()).filter(Boolean):[]),t.to];t.routingNote='';t.timetable=null;t.routeBasis='OSM 网络推算';if(t.mode==='rail'){if(t.via.trim())t.routeBasis='人工途经站约束 + OSM';else if($('routing').value==='timetable'){try{tell('查询历史停站：'+(t.raw['班次']||'未填车次'));t.timetable=await Timetable.lookup(t,{signal:controller?.signal});names=t.timetable.names;t.routeBasis='历史停站约束 + OSM（参考）'}catch(e){t.routingNote='未使用时刻表：'+e.message}finally{}}if(cancel)throw Error('已停止')}const routeKey='route:v3:'+($('routing').value==='overpass'?'overpass:':'brouter:')+JSON.stringify({names,operator:StationMatch.context(t).label,overrides:t.overrides||{},version:t.timetable?.version||'',train:t.timetable?.train||''});if(t.mode==='rail'){const saved=await Services.read(routeKey,30*86400000);if(saved){t.path=saved.path;t.nodeIds=saved.nodeIds;t.routeBasis=saved.routeBasis||t.routeBasis;t.status='已生成 · 复用缓存铁路轨迹';return}}const points=await locateMany(names,t);if(t.mode==='air'){if(Core.km(points[0],points.at(-1))<.001)throw Error('出发与到达机场坐标相同，无法生成航线');t.path=Core.ellipse(points[0],points.at(-1))}else if($('routing').value!=='overpass'){t.path=await RailService.route(points,controller?.signal,tell);delete t.nodeIds;t.routeBasis+=' · BRouter';await Services.write(routeKey,{path:t.path,routeBasis:t.routeBasis})}else{let full=[],nodeIds=[];const shared=points.length>2&&Math.max(...points.map(p=>Core.km(points[0],p)))<100?await railNetwork(points,t):null;for(let i=1;i<points.length;i++){let leg=await railway(i===1?points[0]:full.at(-1),points[i],i>1,nodeIds.at(-1),t,shared);if(i>1&&leg.nodeIds?.[0]!==nodeIds.at(-1))throw Error('途经站轨道节点不连续，无法生成完整线路');full.push(...(i===1?leg:leg.slice(1)));nodeIds.push(...(i===1?leg.nodeIds:leg.nodeIds.slice(1)))}if(full.length<2)throw Error('无法得到有效轨迹，请核对起终站或途经站');t.path=full;t.nodeIds=nodeIds;await Services.write(routeKey,{path:full,nodeIds})}t.status=t.mode==='air'?'已生成 · 机场间椭圆弧线':'已拟合 · '+t.routeBasis;}
async function run(targets){
 if(busy)return;busy=true;cancel=false;controller=new AbortController();$('stop').hidden=false;for(const id of ['file','sheet','routing'])$(id).disabled=true;
 try{render();let i=0;for(const t of [...targets].sort((a,b)=>(a.mode==='air'?0:1)-(b.mode==='air'?0:1))){if(cancel)break;t.status='正在匹配…';tell('正在生成 '+(++i)+' / '+targets.length+' · '+t.from+' → '+t.to);render();try{await generate(t)}catch(e){t.error=cancel?'已停止':e.message;if(e.candidates)t.candidates={name:e.station,items:e.candidates}}render();if(!cancel)await new Promise(r=>setTimeout(r,0))}}
 finally{busy=false;$('stop').hidden=true;for(const id of ['file','sheet','routing'])$(id).disabled=false;render();fit();tell((cancel?'已停止；':'处理完成；')+trips.filter(t=>t.path).length+' 条已生成，'+trips.filter(t=>t.error).length+' 条待处理。点击记录可修正。')}
}
$('run').onclick=()=>run(trips.filter(t=>!t.path));$('stop').onclick=()=>{cancel=true;controller?.abort()};
function showTrip(t){if(!t)return;fit(displayPaths().get(t.id)||[]);modal('<h2>'+esc(t.from)+' → '+esc(t.to)+'</h2><p>'+esc(t.time?.label||'日期未知')+' '+esc(t.time?.departure||'')+'</p><p>'+esc(t.time?.note||'')+'</p><p>'+esc(t.sheet)+' · 第 '+t.row+' 行</p><pre>'+esc(Object.entries(t.raw).map(([k,v])=>(k==='腐败率'?'每公里单价':k)+'：'+v).join('\n'))+'</pre><p>'+esc(t.routeBasis||'')+'</p><p>'+esc(t.timetable?.source||t.routingNote||'')+'</p><p>'+esc(t.timetable?.names.join(' → ')||'')+'</p><p class="bad">'+esc(t.error)+'</p><label>交通方式<select id="mode"><option value="rail">铁路</option><option value="air">飞行</option></select></label><label>人工途经站（可参考路路通核对，按顺序用 ; 分隔）<input id="via" value="'+esc(t.via)+'"></label>'+(t.candidates?'<label>选择 '+esc(t.candidates.name)+' 的位置<select id="candidate"><option value="">请选择…</option>'+t.candidates.items.map((c,i)=>'<option value="'+i+'">'+esc(c.label)+'</option>').join('')+'</select></label>':'')+'<label>出发地手动坐标（纬度,经度，可留空）<input id="fromXY" placeholder="31.1979,121.3363" value="'+esc(t.overrides?.[t.from]?.join(',')||'')+'"></label><label>到达地手动坐标（纬度,经度，可留空）<input id="toXY" value="'+esc(t.overrides?.[t.to]?.join(',')||'')+'"></label><p id="editError"></p><button class="primary" id="retry" '+(busy?'disabled':'')+'>保存并重新生成</button>');$('mode').value=t.mode;$('retry').onclick=()=>{try{const overrides={...(t.overrides||{})};for(const [id,n] of [['fromXY',t.from],['toXY',t.to]]){const v=$(id).value.trim();if(v){let p=v.split(/[,，]/).map(Number);if(p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>85||Math.abs(p[1])>180)throw Error('坐标格式应为 纬度,经度，纬度范围 ±85°');overrides[n]=p}else delete overrides[n]}if(t.candidates&&$('candidate').value!=='')overrides[t.candidates.name]=t.candidates.items[Number($('candidate').value)].xy;t.overrides=overrides;t.mode=$('mode').value;t.via=$('via').value;$('dialog').close();run([t])}catch(e){$('editError').textContent=e.message}}}
$('export').onclick=()=>{let data=collection();if(!data.features.length)return tell('当前筛选下没有可导出的轨迹');let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'})),a=document.createElement('a');a.href=url;a.download='行迹-轨迹.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('routing').onchange=()=>{if(busy)return;for(const t of trips)if(t.mode==='rail'){delete t.path;delete t.nodeIds;t.status='线路依据已变更，待重新生成';t.error='';t.timetable=null;t.routingNote=''}render();tell('铁路线路依据已变更，请重新生成轨迹')};
$('clear').onclick=()=>{if(busy)return tell('请先停止正在进行的生成任务');trips=[];book=null;cache.clear();$('sheetBox').hidden=true;render();tell('已清空；可导入新的行程表')};

$('archive').onclick=async()=>{if(busy||!trips.length)return tell('请先导入行程，且等待当前任务完成');busy=true;cancel=false;controller=new AbortController();$('stop').hidden=false;for(const id of ['file','sheet','routing','archive'])$(id).disabled=true;render();try{const r=await Timetable.archive(trips,{signal:controller.signal,onProgress:p=>tell('历史缓存 '+p.done+'/'+p.total+' · '+p.train+' · '+p.version)});tell('历史缓存完成：'+r.ok+' 份有停站表，'+r.missing+' 份无此车次，'+r.errors+' 份查询失败。按年代表快照及行程日期缓存，并非所有日期全量数据。')}catch(e){tell(e.message)}finally{busy=false;$('stop').hidden=true;for(const id of ['file','sheet','routing','archive'])$(id).disabled=false;render()}};
